tool_input.command:
cd /home/runner/czaba-project/store; M=../tmp/studio-real-loop/a-round-219/mutants; rm -f $M/*.log $M/f-raw-output.txt; MOD=app/lib/third-party-licenses.ts; TST=app/lib/__tests__/third-party-licenses.test.ts; NOT=THIRD_PARTY_NOTICES.md
sha256sum $MOD $TST $NOT > $M/before.sha256
cat > $M/apply-mutant.mjs <<'EOF'
import { readFileSync, writeFileSync } from 'node:fs';
const [name, mod, tst, notices] = process.argv.slice(2);
const edits = {
  a: [[mod, 'return combineOrClassifications(parts);', 'return combineAndClassifications(parts);']],
  b: [[mod, " || readTrueProperty(entry, 'dev')) {", ') {']],
  c: [[mod, '  return new SpdxExpressionParser(tokens)', "  if (/GPL/i.test(expression)) {\n    return 'copyleft';\n  }\n  return new SpdxExpressionParser(tokens)"]],
  d: [[mod, '      exception.name === runtimePackage.name && exception.version === runtimePackage.version,', '      exception.name === runtimePackage.name,']],
  e: [[notices, /^\| limiter \| 1\.1\.5 \|.*\n/m, '']],
  f: [[notices, /^\| limiter \| 1\.1\.5 \|.*\n/m, ''], [tst, 'await expect(renderThirdPartyNotices(realLock))', 'expect(renderThirdPartyNotices(realLock))']],
  g: [[mod, /(THIRD_PARTY_LICENSE_EXCEPTIONS: readonly ThirdPartyLicenseException\[\] = \[)[\s\S]*?\n\];/, (_m, head) => `${head}];`]],
};
for (const [path, from, to] of edits[name]) {
  const source = readFileSync(path, 'utf8');
  const next = source.replace(from, to);
  if (next === source) { throw new Error(`mutant ${name}: no change in ${path}`); }
  writeFileSync(path, next);
}
EOF
for m in a b c d e f g; do cp $MOD /tmp/mod.bak; cp $TST /tmp/tst.bak; cp $NOT /tmp/not.bak; node $M/apply-mutant.mjs $m $MOD $TST $NOT || echo APPLY-FAILED; { echo "MUTANT $m"; diff -u /tmp/mod.bak $MOD; diff -u /tmp/tst.bak $TST; diff -u /tmp/not.bak $NOT; echo "--- CI=true npx vitest run $TST (no -u)"; CI=true npx vitest run $TST 2>&1 | sed 's/\x1b\[[0-9;]*m//g' > /tmp/out.txt; echo "rc=$?"; grep -E '^ FAIL ' /tmp/out.txt | sed 's/.*test.ts > //' | sort -u; grep -E 'Tests |not awaited' /tmp/out.txt | sort -u | cut -c1-220; } > $M/$m.log 2>&1; cp /tmp/mod.bak $MOD; cp /tmp/tst.bak $TST; cp /tmp/not.bak $NOT; sha256sum -c --quiet $M/before.sha256 && echo "restored: sha256 OK" >> $M/$m.log; done
for m in a b c d e f g; do echo "== $m"; sed -n '/^--- CI/,$p' $M/$m.log | grep -v '^--- CI' | cut -c1-150; done; sha256sum -c $M/before.sha256
